"""Order totals for example-service. A fixture, not a real shop."""

VAT = 0.22


def subtotal(prices: list[float]) -> float:
    return sum(prices)


def with_vat(amount: float) -> float:
    return amount * (1 + VAT)


def describe(amount: float) -> str:
    return "total: " + str(amount)

